    [2200] = "Busca pistas de la ubicación actual del collar de Talvash dentro de Uldaman. El paladín asesinado que mencionó fue la última persona que lo tenía.",
    [2201] = "Encuentra el rubí, el zafiro y el topacio que están desperdigados por Uldaman. Cuando los tengas, contacta con Talvash del Kissel mediante la ampolla de adivinación que él te dio. A través del diario, sabes que... *El rubí está escondido en una zona de Forjatiniebla con barricadas. *El topacio permanece oculto en una urna en una de las zonas de los troggs, cerca de algunos enanos de la Alianza. *El zafiro obra en poder de Grimlok, el líder de los troggs, según él mismo afirma.",
    [2202] = "Llévale 12 setas magenta a Jarkal Musgofusión en Kargath.",
    [2203] = "Usa las vasijas de taumaturgia vacías con los dragones guardianes agostados de las Tierras Inhóspitas. Cuando las hayas llenado, llévaselas a Jarkal Musgofusión en Kargath.",
    [2204] = "Obtén una fuente de energía del ensamblaje más poderoso que encuentres en Uldaman, y entrégasela a Talvash del Kissel en Forjaz.",
    [2205] = "Entrega el paquete de Keryn Sylvius al maestro Mathias Shaw que está en el Cuartel de Ventormenta.",
    [2206] = "Encuentra al maestro de embarcadero Defias y recupera el calendario de envíos para el maestro Mathias Shaw.",
