    [2380] = "Ve a Orgrimmar, al Circo de las Sombras, y habla con Shenthul.",
    [2381] = "Llévale el tesoro de los Mares del Sur a Desdio el Desdichado en Trinquete. No olvides conseguir una G.E.A.Q. y herramientas de ladrones del aparato Gizmotrónico de Wrenix. Necesitarás todo eso para completar tu misión. Si te atacaran unos loros anormalmente agresivos, ¡usa la G.E.A.Q.!|n|n",
    [2382] = "Viaja a Trinquete y habla con Desdio el Desdichado.",
    [2383] = "Lee el Pergamino simple y habla con Frang en el Valle de los Retos.",
    [2398] = "Encuentra a Baelog en Uldaman.",
