    [3119] = "Lee el sigilo sacralizado y habla con Shanda en Aldrassil.",
    [3120] = "Lee el sigilo verdeante y habla con Mardant Fuerterroble, en el árbol Aldrassil de Cañada Umbría.",
    [3121] = "Lleva la cabeza reducida a Neeru Hojafuego en Orgrimmar.",
    [3122] = "Entrega la faltriquera de hierbas de Neeru al médico brujo Uzer'i en Feralas.",
    [3123] = "Viaja a las Tierras del Interior y encuentra a los lechúcicos. Mata a 10 y usa la vasija de muisek para encoger y capturar a los lechúcicos caídos. Lleva 10 muiseks de lechúcico y la vasija de muisek al médico brujo Uzer'i en Feralas.",
    [3124] = "Acaba con 10 hipogrifos Plumavieja de cualquier tipo y utiliza la vasija de muisek para encogerlos y capturarlos.",
    [3125] = "Mata a 8 duendes dardo o duendes dragón. Utiliza la vasija de muisek para reducir y capturar a los dragones feéricos caídos.",
    [3126] = "Mata a 3 caminabosques deambulantes. Utiliza la vasija de muisek de antárbol para reducir y capturar a los antárboles caídos.",
    [3127] = "Mata a 7 caminantes de la tierra o gigantes del risco. Utiliza la vasija de muisek para reducir y capturar a los gigantes monteses caídos.",
    [3128] = "Lleva 2 troncos astillados, 6 minerales taraceados, 20 tendones resistentes y 40 trozos metálicos al médico brujo Uzer'i al Campamento Mojache.",
