    [3130] = "Preséntate ante Latronicus Lanzaluna, en el Bastión Plumaluna.",
    [3141] = "Escucha la historia de Loramus Thalimedes.",
    [3161] = "Marvon Buscarroblones de Tanaris quiere que reúnas 30 adornos de gahz'rilo.",
    [3181] = "Lleva el cuerno enorme de Margol a la montaraz Guijarro.|n",
    [3182] = "Lleva el cuerno enorme de Margol al comisario Torio en Forjaz.",
    [3201] = "Lleva el certificado de autenticidad a la montaraz Guijarro.",
    [3221] = "Habla con el boticario Renferrel en El Sepulcro.",
    [3261] = "Habla con Jorn Vidente del Cielo en el Campamento Taurajo.",
    [3281] = "Llévale la plata robada a Gazrog en El Cruce.",
    [3301] = "Habla con Mura Tótem de Runa en el Sepulcro.",
    [3321] = "Espera a que Trenton acabe su trabajo.",
    [3341] = "Andrew Brownell quiere que mates a Amnennar el Gélido y que le lleves su cráneo.",
    [3361] = "Llévale la caja de Félix, el cofre de Félix y el cubo de tornillos de Félix a Félix Rayaullido en Yunquemar.",
