    [3367] = "Ayuda a Dorius a volver a Forjaz.|n",
    [3368] = "Lleva la carta chamuscada a Thorius a Forjaz. Está en la Sala de los Expedicionarios.",
    [3369] = "Lleva el Fragmento de Pesadilla a Hamuul Tótem de Runa en el Alto de los Ancestros.",
    [3370] = "Lleva el Fragmento de Pesadilla a Mathrengyl Garroso de Darnassus.",
    [3371] = "Vuelve a La Garganta de Fuego y encuentra a la unidad arqueológica de Dorius.",
    [3372] = "Encuentra el artefacto misterioso que protegen los idólatras de Martillo Crepuscular en el cuadrante noroeste de La Garganta de Fuego y tráelo al altar de Suntara en la Fosa de la Escoria.",
    [3373] = "Coloca la esencia de Eranikus en la fuente de esencia situada en su guarida del Templo Sumergido.",
    [3374] = "Llévale la piedra de juramento del Vuelo de Ysera y la esencia encadenada de Eranikus a Itharius, que está en el Pantano de las Penas. Una vez allí, deberás decidir si quieres ayudar al Vuelo de Ysera o no.",
    [3375] = "Lleva 1 poción de maná, 1 trozo de carbón y néctar dulce a Talvash del Kissel a Forjaz. Te dará una ampolla de adivinación.",
    [3376] = "Lleva la cabeza del Jefe Cornapunta Mantospina a la Valiente Pluma de Viento en Mesa de la Nube Roja.",
    [3377] = "Escucha a Zamael.",
    [3378] = "Lleva el rezo a Elune a Astarii Buscaestelar a Darnassus.",
    [3379] = "Mata a los furtivos Sedaumbría de La Garganta de Fuego. Nilith cree que son 5. Ve a ver a Nilith en La Garganta de Fuego cuando hayas terminado.",
    [3380] = "Encuentra a Marvon Buscarroblones en Tanaris.",
    [3382] = "Defiende a la capitana Vanessa Beltis, su tripulación y los pasajeros del Explorador del horizonte frente al ataque de los nagas. La capitana Vanessa Beltis tiene que sobrevivir.",
    [3385] = "Mata al maestro de comercio Kovic y a su esbirro, Clonk. Lleva su cartera a Nilith.",
    [3402] = "Habla con Vizzklick en Gadgetzan.",
    [3441] = "Escucha a Velarok Espada del Viento.",
    [3442] = "Lleva 4 corazones de llama y 4 globos de aceite gólem a Velarok Espada del Viento.",
    [3443] = "Lleva 8 dagas bañadas en torio a Velarok Espada del Viento.",
    [3444] = "Recupera el círculo de piedra del taller de Marvon Buscarroblones, en Trinquete.",
    [3445] = "Encuentra a Marvon Buscarroblones en Tanaris.",
    [3446] = "Encuentra el Altar de Hakkar en el Templo Sumergido, en el Pantano de las Penas.",
    [3447] = "Ve al Templo Sumergido y descubre el secreto oculto en el círculo de estatuas.",
    [3448] = "Habla con Tymor en Forjaz.",
    [3449] = "Haz calcos de la Runa de Beth'Amara, la Runa de Jin'yael, la Runa de Markri y la Runa de Sael'hai. Luego ve a la isla frente a la península meridional de Azshara y avisa al piloto Xiggs Botafuego para que recoja los calcos.",
    [3450] = "Habla con Xiggs Botafuego en Forjaz.",
    [3451] = "Habla con Xiggs Botafuego para que te dé una pistola de bengalas en Forjaz.",
    [3452] = "Lleva un Símbolo de Ragnaros a Velarok Espada del Viento.",
    [3453] = "Espera a que Velarok Espada del Viento termine la antorcha de reprensión.",
    [3454] = "Coge la antorcha de reprensión.",
    [3461] = "Devuelve el juego de calco a Tymor, que está en Forjaz.",
    [3462] = "Habla con mi enviado, el escudero Maltrake.",
    [3463] = "Entra en las 4 torres del centinela e incéndialas con la antorcha de reprensión.|n",
    [3481] = "Abre el cofre.",
    [3501] = "Llévale a Kum'isha trozos draenetistas imperfectos y te recompensará por cada fragmento entregado.|n",
    [3502] = "Llévale a Kum'isha trozos draenetistas imperfectos. Cualquier forma de monstruo de Las Tierras Devastadas podría llevar uno de estos fragmentos.",
    [3504] = "Entrega la carta lacrada a Ag'tor Puñosangre en Azshara.",
    [3505] = "Mata a 10 reivindicadores y 10 peritos elfos de sangre antes de buscar el campamento de Maga Rimtori. Una vez allí, busca algo que sea importante para ella, algo con lo que provocar un combate.",
    [3506] = "Destruye el cristal de enfoque Arcano de Maga Rimtori y entonces mátala. Lleva su cabeza a Ag'tor Puñosangre a Azshara.",
    [3507] = "Habla con Belgrom Destrozarroca en Orgrimmar.",
    [3508] = "Espera que Loramus acabe el hechizo de ilustración.",
    [3509] = "Habla con Lord Arkkoroc en Azshara. Empieza tu búsqueda en la orilla para encontrar el Templo de Arkkoran.",
    [3510] = "Mata a Hetaera y lleva la cabeza ensangrentada, la cabeza golpeada y la cabeza amoratada a Lord Arkkoroc.",
    [3511] = "Llévale el temple a Loramus Thalimedes.",
    [3512] = "Viaja a la parte este de Cuna del Invierno y habla con Umbranse el Hablaalmas.",
    [3513] = "Llévale el pergamino rúnico de la torre de vigilancia norte en Los Baldíos.",
    [3514] = "Mata a la jefa de El Cubil del Espolón, Rynthariel la Maestra de llaves.",
    [3517] = "Encuentra la tablilla de Beth'Amara, la tablilla de Jin'yael, la tablilla de Markri y la tablilla de Sael'hai antes de volver junto a Jediga en Azshara.",
    [3518] = "Llévale la tablilla de Beth'Amara a Magatha en Cima del Trueno.",
    [3519] = "Habla con Dirania Brillargente en Cañada Umbría.",
