    [3521] = "Recoge 7 champiñones jacintos, 4 lirios alunados y 1 icor tejemadera para Dirania Brillargente en Cañada Umbría.",
    [3522] = "Llévale el antídoto de Iverron a Iverron antes de que se acabe el tiempo. Lo encontrarás junto a la cueva situada al norte.",
