    [5678] = "Habla con la suma sacerdotisa Laurena en Ventormenta.",
    [5713] = "Protege a la centinela Aynasha y luego ve a Vallefresno, a la Atalaya de Maestra, y habla con Onaeya.",
    [5721] = "Coloca el fardo de reliquias en la plaza de Villa Darrow. Impide que Davil Fuegoluz muera antes que Horgus. Impide que el capitán Rutagrana muera hasta que aparezca Rutagrana el Corrompido. Derrota a Rutagrana el Corrompido. Habla con el espíritu de Joseph Rutagrana cuando aparezca en la Plaza de la Ciudad y luego habla con Pamela en su casa.",
    [5722] = "Inspecciona la Sima Ígnea en busca del cuerpo de Maur Tótem Siniestro y comprueba si porta algún objeto de interés.",
    [5723] = "Localiza la Sima Ígnea en Orgrimmar y después mata a 8 troggs Furia Ardiente y 8 chamanes Furia Ardiente y después ve a ver de nuevo a Rahauro a Cima del Trueno.",
    [5724] = "Lleva la cartera de Tótem Siniestro hasta Rahauro, en Cima del Trueno.",
    [5725] = "Llévale los libros Hechizos de las Sombras y Encantamientos desde el infierno a Varimathras, que está en Entrañas.",
    [5726] = "Lleva una insignia de Teniente a Thrall a Orgrimmar.",
    [5727] = "Lleva la insignia de Teniente a Neeru Hojafuego. Averigua si cree que eres miembro de Filo Ardiente; luego ve a ver a Thrall a Orgrimmar.",
    [5728] = "Mata a Bazzalan y a Jergosh el Convocador y ve a ver a Thrall a Orgrimmar.",
    [5729] = "Habla con Neeru Hojafuego en Orgrimmar.",
    [5730] = "Habla con Thrall en Orgrimmar y cuéntale lo que has averiguado.",
    [5741] = "Consigue el Cetro de Luz y llévaselo a Azore Aldamort a la torre de Ethel Rethor.|n",
    [5742] = "Escucha lo que Tirion Vadín tiene que contarte.",
    [5761] = "Ve a la Sima Ígnea, mata a Taragaman el Hambriento y llévale su corazón a Neeru Hojafuego a Orgrimmar.",
    [5762] = "Lleva el cajón de Kravel a Hemet Nesingwary en Tuercespina.",
    [5763] = "Lleva el cuerno de kodo de Roon a Hemet Nesingwary en Tuercespina.",
    [5781] = "Viaja a La Subgranja, en la sección más meridional de las Tierras de la Peste del Este, y recupera el Martillo de Taelan. Cuando hayas cumplido tu objetivo regresa con Tirion Vadín.",
    [5801] = "Lleva el molde para llave esqueleto y 2 barras de torio a la cima de la Cresta del Penacho en Llamas en el Cráter de Un'Goro. Utiliza el molde para llave esqueleto en el lago de lava para forjar la llave esqueleto sin terminar. Llévale la llave esqueleto sin terminar al alquimista Arbington al Alto del Orvallo, en las Tierras de la Peste del Oeste.",
    [5802] = "Lleva el molde para llave esqueleto y 2 barras de torio a la cima de la Cresta del Penacho en Llamas en el Cráter de Un'Goro. Utiliza el molde para llave esqueleto en el lago de lava para forjar la llave esqueleto sin terminar. Llévale la llave esqueleto sin terminar al boticario Dithers a El Baluarte, en las Tierras de la Peste del Oeste.",
    [5803] = "Destruye a Araj el Invocador y lleva el Escarabeo de Araj al alquimista Arbington en el Alto del Orvallo, en las Tierras de la Peste del Oeste.",
    [5804] = "Destruye a Araj el Invocador y lleva el Escarabeo de Araj al boticario Dithers en El Baluarte, en las Tierras de la Peste del Oeste.",
    [5821] = "Escolta la caravana Gizelton a través del poblado de los centauros Kolkar. Habla con Smeed en el Campamento de los Mezclatornillos para recibir tu recompensa.",
    [5845] = "Viaja a Vallenorte, en la zona noreste de las Tierras de la Peste del Este, y recupera el Símbolo de Honor perdido. Cuando hayas cumplido tu objetivo regresa con Tirion Vadín.",
    [5846] = "Viaja a la isla de Castel Darrow, en la región sur del centro de las Tierras de la Peste. Allí, busca pistas sobre el paradero del cuadro.",
    [5848] = "Viaja a Stratholme, en la zona norte de las Tierras de la Peste. En El Bastión Escarlata encontrarás el cuadro 'Del amor y la familia', oculto tras otra pintura que representa las lunas gemelas de nuestro mundo. Devuelve la pintura a Tirion Vadín.",
    [5861] = "Viaja a la Tumba de Uther, en el sur de las Tierras de la Peste. Enseña a Myranda la Fada el obsequio de Tirion.",
    [5862] = "Habla con Myranda para conseguir la Ilusión Escarlata. Bajo el poder de la Ilusión Escarlata viaja a la Vega del Amparo y entrega el obsequio de Tirion al alto señor Taelan Vadín. La Vega del Amparo está al Norte, Taelan seguramente estará en el interior de la Fortaleza de Mardenholde.",
    [5863] = "Andi Lynn de Gadgetzan quiere que destruyas la Base Machacaduna y para conseguirlo tendrás que matar 10 toscos Machacadunas, 10 déspotas Machacadunas y a Gor'marok el Devastador.",
    [5881] = "Maggran quiere que le entregues una carta a Grish Largo Camino en El Gran Elevador, en Los Baldíos.",
    [5892] = "Lleva 10 suministros de Ferrohondo al intendente de la Alianza en Dun Baldar.",
    [5893] = "Lleva 10 suministros de Dentefrío al intendente de la Horda en el Bastión Lobo Gélido.",
    [5901] = "Utiliza el tarro de termitas vacío en los montones de termitas de las Tierras de la Peste del Este. Cuando hayas reunido 100 termitas de las Tierras de la Peste, vuelve con Mickey Levine, que está en El Baluarte, en Claros de Tirisfal.",
    [5902] = "Encuentra un lugar adecuado en el centro del Aserradero Crestanorte, en las Tierras de la Peste del Oeste, para colocar la barrica de termitas de las Tierras de la Peste.",
    [5903] = "Utiliza el tarro de termitas vacío en los montones de termitas de las Tierras de la Peste del Este. Cuando hayas reunido 100 termitas de las Tierras de la Peste, vuelve con Nathaniel Dumah al Campamento del Orvallo en las Tierras de la Peste del Oeste.",
    [5904] = "Encuentra un lugar adecuado en el centro del Aserradero Crestanorte, en las Tierras de la Peste del Oeste, para colocar la barrica de termitas de las Tierras de la Peste.",
    [5921] = "Utiliza el hechizo \"Teletransporte: Claro de la Luna\" para viajar a Claro de la Luna. Cuando llegues, ve al poblado Amparo de la Noche y habla con Dendrita Rafagaestelar.",
    [5922] = "Utiliza el hechizo \"Teletransporte: Claro de la Luna\" para viajar a Claro de la Luna. Cuando llegues, ve al poblado Amparo de la Noche y habla con Dendrita Rafagaestelar.",
    [5923] = "Habla con Mathrengyl Garroso en el Enclave Cenarion de Darnassus.",
    [5924] = "Habla con Mathrengyl Garroso en el Enclave Cenarion de Darnassus.",
    [5925] = "Habla con Mathrengyl Garroso en el Enclave Cenarion de Darnassus.",
    [5926] = "Habla con Turak Tótem de Runa en Alto de los Ancestros, en Cima del Trueno.",
    [5927] = "Habla con Turak Tótem de Runa en Alto de los Ancestros, en Cima del Trueno.",
    [5928] = "Habla con Turak Tótem de Runa en Alto de los Ancestros, en Cima del Trueno.",
    [5929] = "Busca al espíritu del gran oso al noroeste de Claro de la Luna y aprende lo que tenga que enseñarte sobre la naturaleza del oso. Después ve a hablar con Dendrita Rafagaestelar a Amparo de la Noche, en Claro de la Luna.",
    [5930] = "Busca al espíritu del gran oso al noroeste de Claro de la Luna y aprende lo que tenga que enseñarte sobre la naturaleza del oso. Después ve a hablar con Dendrita Rafagaestelar a Amparo de la Noche, en Claro de la Luna.",
    [5931] = "Vuelve a Darnassus para hablar con Mathrengyl Garroso en el Enclave Cenarion.",
    [5932] = "Vuelve a Cima del Trueno para hablar con Turak Tótem de Runa en Alto de los Ancestros.",
    [5941] = "Lleva el montón de reliquias a Cromi a Andorhal.",
    [5942] = "Lleva la llave de Joseph al cofre de Joseph.",
    [5943] = "Escolta la caravana Gizelton a través del Aquelarre Mannoroc. Habla con Smeed en el Campamento de los Mezclatornillos para recibir tu recompensa.",
    [5944] = "Escolta a Taelan Vadín fuera de la Vega del Amparo.",
    [5961] = "Habla con Nathanos Clamañublo en las Tierras de la Peste del Este. Se dice que ahora vive en la Hacienda de Marris.",
    [5981] = "Rivern Ventogélido quiere que mates 4 gigantes Machacahielo y 4 valedores Machacahielo.",
    [6001] = "Utiliza el polvo de luna Cenarion en la piedra de lechúcico lunar de Auberdine para invocar a Garraluna. Luego tendrás que enfrentarte a Garraluna y ganar la fuerza física y de corazón que posee. Cuando hayas acabado, vuelve a Darnassus y habla con Mathrengyl Garroso.",
    [6002] = "Aplica el polvo de luna Cenarion a la piedra de lechúcico lunar que se encuentra entre Mulgore y Los Baldíos para provocar a Garraluna. Hecho esto, has de enfrentarte a Garraluna para obtener la fuerza física y de corazón que posee. Habla con Turak Tótem de Runa en Cima del Trueno cuando hayas acabado.",
    [6004] = "Mata a 2 médicos Escarlata, 2 cazadores Escarlata, 2 magos Escarlata y 2 caballeros Escarlata antes de regresar con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste.",
    [6021] = "Lleva la cabeza de Zaeldarr al custodio Alen a la Capilla de la Esperanza de la Luz.",
    [6022] = "Viaja al Cruce de Corin al este y mata a los miembros de la Plaga que habitan allí. Recoge 7 piezas de putrefacción viva en 10 minutos. Utiliza el mortero y el majadero para convertir la putrefacción viva en putrefacción coagulada.",
    [6023] = "Mata al montero Radley y al hidalgo Durgen antes de regresar con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste.",
    [6024] = "Mata al infiltrador Hameya. Usa su llave en el túmulo detrás de La Subgranja.",
    [6025] = "Entra en la Vega del Amparo y busca un punto elevado desde el que puedas ver la ciudad y calcular las fuerzas de la Cruzada Escarlata. Cuando lo hayas hecho regresa con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste.",
    [6026] = "Smokey LaRue quiere que consigas 2 barras de torio, 1 vara dorada, 8 bombas de gran carga y 8 disparadores inestables. Tendrás que encontrar a un herrero y a un ingeniero para conseguir esos objetos.",
    [6027] = "Consigue el Libro de los Ancestros y llévaselo a Azore Aldamort a la torre de Ethel Rethor.|n",
    [6028] = "Entrega el informe de Vista Eterna a la oficial Argenta Purocorazón en el Campamento del Orvallo, en las Tierras de la Peste del Oeste.",
    [6029] = "Entrega el informe de Vista Eterna al oficial Argenta Garush en El Baluarte, en las Tierras de la Peste del Oeste.",
    [6030] = "Entrega el libro, \"Estudios sobre la Comunicación con los Espíritus\", al duque Nicolas Zverenhoff en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.",
    [6031] = "Llévale 30 paños rúnicos a Meilosh, que está en el Bastión Fauces de Madera.",
    [6032] = "Llévale 2 retales de tela lunar a Meilosh, que está en el Bastión Fauces de Madera.",
    [6041] = "Viaja al Bosque de la Peste, al noroeste de la Esperanza de la Luz. Destruye 8 estructuras de la Plaga utilizando el compuesto especial de Smokey en la marca de detonación que hay en el interior de cada edificio. Smokey ha hecho marcar los zigurats y los degolladeros. Cuando plantes la bomba, sal del edificio y disfruta del espectáculo. Por cierto, el compuesto especial de Smokey es... bastante inestable.",
    [6042] = "Mata a 20 murcipestes tóxicos y 10 murcipestes monstruosos. Vuelve con Nathanos Clamañublo cuando hayas acabado.",
    [6061] = "Usa la fusta de doma para domar un zancudo de llanura adulto. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre.",
    [6062] = "Usa la fusta de doma para domar un jabalí jaspeado temible. Practica un poco y devuélvele la fusta a Thotar en Cerrotajo.",
    [6063] = "Utiliza la fusta de doma para domar a un rondador Tejemadera. Practica tus habilidades y después devuélvele la fusta de doma a Dazalar, que está en Dolanaar.",
    [6064] = "Usa la fusta de doma para domar a un jabalí del risco grande. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos.",
    [6065] = "Habla con Yaw Crinafilada en el Poblado Pezuña de Sangre, en Mulgore.",
    [6066] = "Habla con Yaw Crinafilada en el Poblado Pezuña de Sangre, en Mulgore.",
    [6067] = "Habla con Yaw Crinafilada en el Poblado Pezuña de Sangre, en Mulgore.",
    [6068] = "Habla con Thotar en Cerrotajo.",
    [6069] = "Habla con Thotar en Cerrotajo.",
    [6070] = "Habla con Thotar en Cerrotajo, en Durotar.",
    [6071] = "Habla con Dazalar en Dolanaar.",
    [6073] = "Habla con Dazalar en Dolanaar, en Teldrassil.",
    [6074] = "Habla con Grif Corazón Salvaje en Kharanos.",
    [6075] = "Ve a hablar con Grif Corazón Salvaje en Kharanos, en Dun Morogh.",
    [6076] = "Ve a hablar con Grif Corazón Salvaje en Kharanos, en Dun Morogh.",
    [6081] = "Habla con Ormak Tirosiniestro en Orgrimmar.",
    [6082] = "Usa la fusta de doma para domar un escórpido acorazado. Practica un poco y devuélvele la fusta de doma a Thotar en Cerrotajo.",
    [6083] = "Usa la fusta de doma para domar un reptador de espuma. Practica un poco y devuélvele la fusta de doma a Thotar en Cerrotajo.",
    [6084] = "Usa la fusta de doma para domar un leopardo de las nieves. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos.",
    [6085] = "Usa la fusta de doma para domar un oso zarpahelada. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos.",
    [6086] = "Habla con Belia Tronagranito en Forjaz.",
    [6087] = "Usa la fusta de doma para domar un acechador de pradera. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre.",
    [6088] = "Usa la fusta de doma para domar un aguilón. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre.",
    [6089] = "Habla con Holt Tronacuerno en el Alto de los Cazadores, en Cima del Trueno.",
    [6101] = "Utiliza la fusta de doma para domar a un acechador sable de la noche. Practica tus habilidades y después devuélvele la fusta de doma a Dazalar, que está en Dolanaar.",
    [6102] = "Utiliza la fusta de doma para domar a un estridador estrígido. Practica tus habilidades y después devuélvele la fusta de doma a Dazalar, que está en Dolanaar.",
    [6103] = "Habla con Jocaste en el Enclave Cenarion de Darnassus.",
    [6121] = "Viaja a Claro de la Luna, al poblado Amparo de la Noche, y habla con Dendrita Rafagaestelar.",
    [6122] = "Recoge agua de Salto de Fonroca a la entrada de la cueva. Entrégale la muestra llena de Salto de Fonroca a Alanndarian Arrullanoche; en Auberdine, en Costa Oscura.",
    [6123] = "Lleva 5 raíces de tierra y 12 hongos lunares a Alanndarian Arrullanoche a Auberdine, para que pueda preparar un bálsamo curativo.",
    [6124] = "Utiliza el bálsamo curativo para animales en los 10 ciervos enfermos que hay en Costa Oscura; el bálsamo debería curarlos. Se han avistado ciervos enfermos desde el sur del Río Fonroca hasta el norte de Auberdine y por toda la zona que lleva hasta el sur de Costa Oscura, donde empieza Vallefresno.",
    [6125] = "Vuelve a Darnassus para hablar con Mathrengyl Garroso en el Enclave Cenarion.",
    [6126] = "Viaja a Claro de la Luna, al poblado Amparo de la Noche, y habla con Dendrita Rafagaestelar.",
    [6127] = "Usa el muestrario de Cima Calígine vacío para recoger una muestra de agua de uno de los estanques de la cima. Luego llévale el muestrario de Cima Calígine lleno a Tonga Tótem de Runa a El Cruce, en Los Baldíos.",
    [6128] = "Llévale 5 raíces de tierra y 5 cuernos de kodo a Tonga Tótem de Runa en El Cruce para que pueda confeccionar un bálsamo curativo.",
    [6129] = "Usa el bálsamo animal curativo sobre las 10 gacelas enfermas que se encuentran en la parte norte de Los Baldíos; así se curarán. Hemos recibido informes según los cuales se han avistado gacelas enfermas por la carretera que va de este a oeste en El Cruce.",
    [6130] = "Vuelve a Cima del Trueno para hablar con Turak Tótem de Runa en Alto de los Ancestros.",
    [6132] = "Escolta a Melizza Zumbala, y luego habla con Hornizz Zumbala en el Cementerio de Kodos en Desolace.",
    [6133] = "Viaja a la frontera norte de las Tierras de la Peste del Este y recupera el Registro de Quel'Thalas. Se encuentra en algún lugar del Refugio Quel'Lithien. También tienes que matar a 8 forestales, 8 zancaminos y 8 leñadores.",
    [6134] = "Llévale 8 ectoplasmas y el cajón de imanes fantasmales a Hornizz Zumbala en Desolace.",
    [6135] = "Encuentra a Alaocaso y mátalo. Recoge un parche de pelaje de Alaocaso de su cadáver y llévaselo a Nathanos Clamañublo. Se dice que Alaocaso vaga por el campo, al norte de la Hacienda de Marris.",
    [6136] = "Encuentra a Borelgore en las planicies del norte de las Tierras de la Peste del Este y destrúyelo. Vuelve junto a Nathanos Clamañublo cuando hayas cumplido la misión.",
    [6141] = "Habla con el hermano Anton en Desolace.",
    [6142] = "Encuentra 10 piezas de carne de almeja blanda y llévaselas a Mai'Lahii a la Aldea Cazasombras.",
    [6143] = "Mata a 7 mirmidones Filozante, 7 nagas Filozante y 5 hechiceras Filozante y luego ve a Cazasombras, en Desolace, a hablar con Drulzegar.",
    [6144] = "Viaja a Entrañas y habla con Varimathras.",
    [6145] = "Vuelve a las Tierras de la Peste del Este y encuentra al mensajero carmesí. Mata al mensajero y recupera la Orden del Gran Cruzado. Lleva el documento a Nathanos Clamañublo y espera sus instrucciones.",
    [6146] = "Viaja a Mano de Tyr, al sureste de la Hacienda de Marris. Una vez allí, da un mordisco a la manzana podrida. Entrega la Orden del Gran Cruzado al señor cruzado Valdemar con la protección de la forma de la Cruzada Escarlata.",
    [6147] = "Vuelve con Nathanos Clamañublo con la nueva información.",
    [6148] = "La Cruzada Escarlata se está moviendo. En algún lugar, a lo largo del camino que va de Mano de Tyr a Stratholme, encontrarás al Oráculo, Demetria, con su escolta. Da caza a Demetria y mátala. Vuelve junto a Nathanos Clamañublo si tienes éxito.",
    [6161] = "Encuentra la llave de plata de Masatormento. Encuentra la llave de oro de Masatormento. Encuentra y abre el cofre de Masatormento.",
    [6162] = "Mata al señor supremo Ror y lleva su garra a Dreka'Sur al Puesto del Veneno de Frondavil.",
    [6163] = "Viaja a Stratholme y mata a Ramstein el Empachador. Coge su cabeza y llévasela como souvenir a Nathanos.",
    [6164] = "Lleva el libro de entradas de Augustus a Augustus el Agraciado en Valle del Terror.",
    [6181] = "Lleva la Nota de Lewis a Thor, el maestro de grifos.",
    [6182] = "Habla con Mathias Shaw en el Casco Antiguo, en Ventormenta. Vive en los Cuarteles.",
    [6183] = "Vuelve a hablar con Mathias Shaw si quieres aceptar esta misión.",
    [6184] = "Vete al Campamento del Orvallo en las Tierras de la Peste del Oeste y reúnete con tu contacto, Flint Sombramás.",
    [6185] = "Explora las Tierras de la Peste del Este en busca de pistas sobre el \"Clamañublo\" y los agentes perdidos del IV:7. Si encuentras alguna insignia del IV:7 llévasela a Flint Sombramás en el Campamento del Orvallo.",
    [6186] = "Regresa a Ventormenta e informa al alto señor Bolvar Fordragón sobre el destino de Nathanos Marris.",
    [6187] = "Reúne un ejército y viaja a las Tierras de la Peste del Este. Lanza un asalto contra Nathanos Clamañublo y cualquier miembro de la Horda que pueda intentar protegerle. Tienes que permanecer alerta, <nombre>. Los de la Horda defenderán al Señor forestal con su vida.",
    [6261] = "Lleva el cajón de Osric a Dungar Tragolargo, el maestro de grifos.",
    [6281] = "Cómprale al maestro de grifos Thor un vuelo en grifo y lleva la Nota de Lewis a Osric Strang, en la tienda Inmunidad Limitada, en el Casco Antiguo de Ventormenta.",
    [6282] = "Maggran Vinculador Terrestre, en el Refugio Roca del Sol, quiere que mates 7 arpías Furia Sangrienta, 7 emboscadoras Furia Sangrienta, 7 destripadoras Furia Sangrienta y 7 malaplumas Furia Sangrienta.",
    [6283] = "Maggran, en el Refugio Roca del Sol, quiere que mates a la desgarradora Furia Sangrienta y le lleves sus restos como prueba de tu hazaña.",
    [6284] = "Mata a Besseleth y lleva el colmillo de Besseleth a Maggran en el Refugio Roca del Sol.",
    [6285] = "Compra un vuelo en grifo hasta la Colina del Centinela al maestro de grifos Dungar Tragolargo y lleva el cajón de Osric a Lewis de la Colina del Centinela.",
    [6301] = "Tammra Campo de Viento, en el Refugio Roca del Sol, quiere que le consigas 10 semillas de Gaia.",
    [6321] = "Lleva la orden de Podrig a Karos Razok.",
    [6322] = "Lleva el cajón de Gordok a Michael Garrett.",
    [6323] = "Compra un viaje en murciélago al maestro de murciélagos Karos Razok y lleva la orden de Podrig a Gordon Wendham en Entrañas.",
    [6324] = "Cómprale un viaje en murciélago hasta el Sepulcro al maestro de murciélagos Michael Garrett y lleva el cajón de Gordon al Guardia de la Muerte Podrig en el Sepulcro.",
    [6341] = "Lleva la colección de Nessa a Vesprystus.",
    [6342] = "Compra un vuelo en hipogrifo hasta Auberdine al maestro de hipogrifos Vesprystus y lleva la colección de Nessa a Laird.",
    [6343] = "Lleva la respuesta de Laird a Nessa Cantosombrío.",
    [6344] = "Habla con Nessa Cantosombrío.",
    [6361] = "Llévale el fardo de pellejos al maestro de jinetes del viento Devrak en El Cruce.",
    [6362] = "Cómprale un trayecto en jinete del viento hasta Cima del Trueno al maestro de jinetes del viento Devrak y llévale el fardo de pellejos a Ahanu en Cima del Trueno.",
    [6363] = "Lleva los artículos de cuero de Ahanu a Tal en Cima del Trueno.",
    [6364] = "Cómprale un viaje en jinete del viento hasta El Cruce al maestro de jinetes del viento Tal y llévale los artículos de cuero de Ahanu a Jahan Ala Halcón.",
    [6365] = "Llévale la carne de Zargh a Devrak en El Cruce.",
    [6381] = "Planta 10 semillas de Gaia en los Túmulos y lleva las semillas de Gaia encantadas restantes a Tammra en el Refugio Roca del Sol.",
    [6382] = "Habla con Senani Corazón Atronador en Puesto del Hachazo, en Vallefresno.",
    [6384] = "Cómprale un trayecto en jinete del viento hasta Orgrimmar al maestro de jinetes del viento Devrak y llévale la carne de Zargh a Gryshka en Orgrimmar.",
    [6385] = "Llévale la carta de Gryshka a Doras en Orgrimmar.",
    [6386] = "Cómprale un trayecto en jinete del viento hasta El Cruce al maestro de jinetes del viento Doras y llévale la carta de Gryshka a Zargh en El Cruce.",
    [6387] = "Llévale la lista de Brocks a Thorgrum Borrelson en Thelsamar.",
    [6388] = "Lleva los picos honorarios a Gryth Thurden en Forjaz.",
    [6389] = "Libera las termitas de las Tierras de la Peste en el Aserradero Crestanorte y luego vuelve con la barrica de termitas de las Tierras de la Peste a Nathaniel Dumah en el Campamento del Orvallo en las Tierras de la Peste del Oeste.",
    [6390] = "Libera las termitas de las Tierras de la Peste en el Aserradero Crestanorte y luego vuelve con la barrica de termitas de las Tierras de la Peste a Mickey Levine en El Baluarte en los Claros de Tirisfal.",
    [6391] = "Contrata un vuelo en grifo a Forjaz con el maestro de grifos Thorgrum Borrelson y llévale la lista de Brock a Golnir Dedorroca, en Forjaz.",
    [6392] = "Contrata un vuelo en grifo a Thelsamar con el maestro de grifos Gryth Thurden para llevarle los picos honorarios a Brock Buscapiedras en Thelsamar.",
    [6393] = "Lleva 10 incendritas a Tsunaman en el Refugio Roca del Sol.",
    [6394] = "Lleva el pico de Thazz'ril al supervisor Thazz'ril.",
    [6395] = "Lleva los restos de Samuel Fipps a la tumba de Marla y luego vuelve con la novicia Elreth.",
    [6401] = "Da las buenas noticias a Tammra Campo de Viento en el Refugio Roca del Sol.|n",
    [6402] = "Viaja hasta la Ciudad de Ventormenta y aventúrate tras las puertas de la ciudad. Habla con el escudero Rowe para que haga saber al mariscal Windsor sobre tu llegada.",
    [6403] = "Sigue a Reginald Windsor por Ventormenta. ¡Protégele del peligro!",
    [6421] = "Explora las profundidades de la cueva del Barranco del Alud y lleva 10 cristales de resonita al Refugio Roca del Sol para que Mor'rogal las estudie.",
    [6441] = "Reúne 16 cuernos de sátiro para Pixie en el Puesto del Hachazo.",
    [6442] = "Llévale 20 cabezas de Colafuria a Marukai en La Ensenada de Zoram.",
    [6461] = "Xen'zilla, en Malaka'Jin, necesita que mates a 10 trepadores Musgondo y a 7 escupevenenos Musgondo.",
    [6462] = "Llévale 8 talismanes trols a Mitsuwa en la Avanzada de Zoram'gar.",
    [6481] = "Abre el barril de resonita con el cristal de resonita encantado y, a continuación, mata a Goggeroc. Vuelve a ver a Mor'rogal para contarle lo ocurrido y entregarle el cristal de resonita encantado.",
    [6482] = "Escolta a Ruul y después habla con Yama Pezuña Nevada en el Puesto del Hachazo.",
    [6501] = "Debes buscar por todo el mundo y encontrar un ser capaz de restaurar el poder del fragmento del Ojo del Dragón. La única información que tienes sobre dicho ser es que existe.",
    [6502] = "Tienes que recuperar la sangre de dragón Negro Campeón, la tiene el general Drakkisath. Puedes encontrar a Drakkisath en su sala del trono, tras las Salas de la Ascensión, en la Cumbre de Roca Negra.",
    [6503] = "Mata a 9 avanzadas de Vallefresno y regresa con Kuray'bin en Puesto del Hachazo.",
    [6504] = "Encuentra las 12 páginas que faltan del manual de instrucciones de trituradora y vuelve a componer con ellas los 3 primeros capítulos. Devuélvele las páginas a Gurda Cicafuria cerca del Puesto del Hachazo.|n",
    [6521] = "Lleva la cabeza del embajador Malcin a Varimathras en Entrañas.",
    [6522] = "Lleva el pergamino pequeño a Varimathras en Entrañas.",
    [6523] = "Escolta a Kaya Pezuña Plana hasta el Campamento Aparaje y ve a ver a Makaba Pezuña Plana cerca del límite sureste de Espolón.|n",
    [6541] = "Preséntate ante Kadrak en la torre de vigilancia en Los Baldíos del Norte.",
    [6542] = "Preséntate ante Kadrak en la torre de vigilancia en Los Baldíos del Norte.",
    [6543] = "Abre el fardo de informes. Lleva los informes Grito de Guerra al explorador Grito de Guerra, al corredor Grito de Guerra y al escolta Grito de Guerra. Preséntate ante Kadrak en la torre de vigilancia norte en los Baldíos con la información que te hayan dado.",
    [6544] = "Escolta a Torek en su ataque sobre la Avanzada Ala de Plata contra Duriel Fuegolunar e informa después a Ertog Colmillorrabioso en el Puesto del Hachazo.",
    [6548] = "Mata a 8 rufianes Tótem Siniestro y a 6 mercenarios Tótem Siniestro. A continuación, ve a ver a Makaba Pezuña Plana cerca del límite sureste de Espolón.|n",
    [6561] = "Llévale la cabeza del señor crepuscular Kelris a Bashana Tótem de Runa en Cima del Trueno.",
    [6562] = "Habla con Je'neu Sancrea en Vallefresno.",
    [6563] = "Llévale 20 zafiros de Aku'Mai a Je'neu Sancrea en Vallefresno.",
    [6564] = "Llévale la nota mojada a Je'neu Sancrea en Vallefresno.",
    [6565] = "Mata a Lorgus Jett en las Cavernas de Brazanegra y vuelve con Je'neu Sancrea en Vallefresno.",
    [6566] = "Escucha a Thrall.",
    [6567] = "Busca a Rexxar. El jefe de guerra te ha indicado dónde encontrarlo. Recorre los caminos de Desolace, entre la Sierra Espolón y Feralas.",
    [6568] = "Entrégale el testimonio de Rexxar a Myranda la Fada en las Tierras de la Peste del Oeste.",
    [6569] = "Viaja a la Cumbre de Roca Negra y recoge 20 ojos de dragauro negro. Cuando hayas terminado tu tarea regresa con Myranda la Fada.",
    [6570] = "Viaja a la Ciénaga de Fuego del Marjal Revolcafango y busca El Cubil de Brasaliza. Cuando estés dentro ponte el Amuleto de Subversión Dracónica y habla con Brasaliza.",
    [6571] = "Reúne los suministros Grito de Guerra: las espadas dentadas Grito de Guerra, cuerda, aceite Grito de Guerra y el envío de hachas de los Grito de Guerra para Locke Okarr en el Puesto del Hachazo.",
    [6582] = "Debes encontrar a Arúspice, el Campeón draco del Vuelo Azul y matarlo. Separa su cráneo de su cuerpo y llévaselo a Brasaliza. Sabes que puedes encontrar a Arúspice en Cuna del Invierno.",
    [6583] = "Destruye al Campeón del Vuelo Verde, Somnus. Lleva su cráneo a Brasaliza.",
    [6584] = "Chronalis, hijo de Nozdormu, custodia las Cavernas del Tiempo en el Desierto de Tanaris. Destrúyelo y lleva su cráneo a Brasaliza.",
    [6585] = "Viaja a Grim Batol y encuentra a Axtroz, el Campeón del Vuelo Rojo. Destrúyelo y hazte con su cráneo. Llévaselo a Brasaliza.",
    [6601] = "Parece que la farsa se acabó. Sabes que el Amuleto de Subversión Dracónica que Myranda la Fada creó para ti no funcionará en la Cumbre de Roca Negra. Quizá debas buscar a Rexxar y explicarle tu situación. Muéstrale el Amuleto Pirodraco apagado. Con suerte, él sabrá qué hacer.",
    [6602] = "Viaja a la Cumbre de Roca Negra y mata al general Drakkisath. Recoge su sangre y entrégasela a Rexxar.",
    [6603] = "Encuentra a Donova Cubilnevado cerca de las fuentes termales de Cuna del Invierno.",
    [6604] = "Habla con Jaron Tallapiedras en Aldea Estrella Fugaz.",
    [6605] = "Habla con Winna Riessgo en Frondavil.",
    [6607] = "Nat Pagle quiere que pesques los siguientes peces: Mahi mahi juncobruma de la Playa Juncobruma del Pantano de las Penas. 1 artillero Sar'theris de la Playa de Sar'theris de Desolace. 1 Ahi de Feralas del Río Verdantis de Feralas. Latipinia azul de La Costa Salvaje de Vega de Tuercespina. Cuando los tengas todos, vuelve a buscar a Nat Pagle.",
    [6608] = "Parece que Lumak piensa que ya no puede enseñarte nada más sobre la pesca. Ve a buscar a su amigo, Nat Pagle, un humano pescador que vive en una isla al sur de Theramore (o eso parece que ha dicho).",
    [6609] = "Ve a Kalimdor, a la ciudad costera de Theramore. Busca una isla hacia el sur. ¡Nat Pagle te espera!",
    [6610] = "Dirge Hojágil quiere que le consigas lo siguiente: 12 huevos gigantes. Pueden ser huevos de los rocs que deambulan por Tanaris o de cualquier otro pájaro de grandes dimensiones. 10 piezas de carne de almeja sabrosa. ¡Las puedes obtener de las almejas, por supuesto! 20 piezas de queso curado de Alterac. ¡Podrás encontrarlo en cualquier quesería! Consigue todo lo que Dirge necesita y llévaselo.",
    [6611] = "Ve a Gadgetzan, en el Desierto de Tanaris, y habla con Dirge Hojágil sobre tus habilidades culinarias.",
    [6612] = "Ve a Gadgetzan, en el Desierto de Tanaris, y habla con Dirge Hojágil sobre tus habilidades culinarias.",
    [6621] = "Coloca el estandarte de Karang en el montículo del tótem de los Maderiza. No permitas que los fúrbolgs destruyan el estandarte. Derrota al jefe Murgut y lleva el tótem de Murgut a Karang Amakkar en Zoram'gar.",
    [6622] = "Salva a pacientes asignando vendas identificativas para atender sus heridas por orden de gravedad. Debes salvar a 15 pacientes antes de que 6 mueran a consecuencia de sus heridas. ¡Ten presente el orden de prioridad! Los soldados con heridas graves mueren antes que los soldados con heridas de gravedad media. Los soldados heridos leves son los que más tardan en morir y solo hay que salvarlos DESPUÉS de identificar y atender a los soldados con heridas graves y medias.",
    [6623] = "Ve a Sentencia, en las Tierras Altas de Arathi, y habla con el doctor Gregory Victor sobre tu incorporación al Dispensario de la Horda.",
    [6624] = "Salva a pacientes asignando vendas identificativas para atender sus heridas por orden de gravedad. Debes salvar a 15 pacientes antes de que 6 mueran a consecuencia de sus heridas. ¡Ten presente el orden de prioridad! Los soldados con heridas graves mueren antes que los soldados con heridas de gravedad media. Los soldados heridos leves son los que más tardan en morir y solo hay que salvarlos DESPUÉS de identificar y atender a los soldados con heridas graves y medias.",
    [6625] = "Ve a Theramore, en el Marjal Revolcafango, y habla con el doctor Gustaf VanHowzen sobre tu incorporación al Dispensario de la Alianza.",
    [6626] = "Mata a 8 guardias de batalla de Rajacieno y 8 tejespinas Rajacieno y 8 cultores Caramuerte y ve a ver a Myriam Lunacanta cerca de la entrada a Zahúrda Rajacieno.",
    [6627] = "Responde la pregunta de Braug Espíritu Tenue con acierto y después habla con él de nuevo. Se quedará en Sierra Espolón hasta que estés listo.",
    [6628] = "Responde la pregunta de Parqual Fintallas con acierto y después habla con él de nuevo. Se quedará en Entrañas hasta que estés listo.",
    [6629] = "Mata a Grundig Nube Negra y a 6 toscos Tótem Siniestro. A continuación, ve a ver a Makaba Pezuña Plana cerca del límite sureste de Espolón.|n",
    [6641] = "Mantén a Muglash a salvo mientras viaja hacia el blandón. Apaga el blandón para ayudarlo y luego lucha contra los nagas para protegerlo. Si tienes éxito, regresa a Avanzada de Zoram'gar e informa al corredor Grito de Guerra sobre la muerte de Vorsha la Azotadora.",
    [6661] = "Utiliza la flauta cazarratas para capturar 5 ratas del subterráneo. Guía a las ratas hasta Monty. No olvides devolver la flauta cuando termines.",
    [6662] = "Lleva el envase de carne misteriosa a Niblis, que está en el Depósito del Tranvía Subterráneo de Ventormenta.",
    [6681] = "Lleva el Sello de Ravenholdt a Fahrad, que está en la Mansión Ravenholdt, en las colinas de Trabalomas. Tendrás que poner a prueba tu ingenio por el camino. Ándate con ojo.",
    [6721] = "Habla con Dazalar en Dolanaar.",
    [6722] = "Habla con Dazalar en Dolanaar, en Teldrassil.",
    [6761] = "Ve a Darnassus, al Enclave Cenarion y habla con Mathrengyl Garroso.",
    [6762] = "Ve a Claro de la Luna, al poblado Amparo de la Noche y habla con Rabine Saturna. Claro de la Luna se encuentra entre Frondavil y Cuna del Invierno; para llegar, tienes que seguir el camino que sale del Bastión Fauces de Madera.",
    [6804] = "Aplica el aspecto de Neptulon a los elementales infectados de las Tierras de la Peste del Este. Lleva 12 de sus brazales discordantes y el aspecto de Neptulon al duque Hydraxis a Azshara.",
    [6805] = "Mata a 15 agitadores sirocosos y 15 estruendores del desierto y vuelve a ver al duque Hydraxis a Azshara.",
    [6821] = "Lleva el ojo del Brasadivino al duque Hydraxis a Azshara.",
    [6822] = "Mata a 1 señor del Fuego, 1 gigante fundido, 1 can del Núcleo anciano y 1 marea de lava y ve a ver al duque Hydraxis a Azshara.",
    [6823] = "Consigue una mención de honor de los Señores del Agua y habla con el duque Hydraxis en Azshara.",
    [6824] = "Lleva las manos de Lucifron, Sulfuron, Gehennas y Shazzrah al duque Hydraxis a Azshara.",
    [6844] = "Lleva el objeto silítido taraceado a Umber, el archivista del Círculo Cenarion, en la aldea de Amparo de la Noche, en el Claro de la Luna.",
    [6845] = "Habla con Rabine Saturna en el poblado Amparo de la Noche, en Claro de la Luna.",
    [6921] = "Llévale el núcleo de las profundidades a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno.",
    [6922] = "Llévale el extraño globo de agua a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno.",
    [6981] = "Viaja a Trinquete y busca a alguien que pueda decirte algo más sobre el fragmento resplandeciente. Entrega el fragmento como se te indique.",
    [6982] = "Lleva 10 suministros de Dentefrío al intendente de la Alianza en Dun Baldar.",
    [6985] = "Lleva 10 suministros de Ferrohondo al intendente de la Horda en el Bastión Lobo Gélido.",
    [7001] = "Encuentra a un Lobo Gélido en el Valle de Alterac. Usa el bozal Lobo Gélido cuando estés junto a él para domarlo. Cuando lo consigas, te seguirá hasta el maestro de establos de los Lobo Gélido. Habla con el maestro de establos para ganarte el crédito por la captura.",
    [7003] = "Utiliza el Ultra-reductor de Zorbin para encoger a cualquier gigante que encuentres en Feralas a un tamaño más manejable. Lleva 15 residuos de miniaturización encontrados en las versiones encogidas de los gigantes a Zorbin Hipnoviento, al embarcadero de La Costa Olvidada de Feralas.",
    [7027] = "Encuentra un carnero de Alterac en el Valle de Alterac. Usa la collera de entrenamiento Pico Tormenta cuando estés junto al carnero de Alterac para domarlo. Cuando lo consigas, te seguirá hasta el maestro de establos. Habla con el maestro de establos para ganarte el crédito por la captura.",
    [7028] = "Recoge 25 tallas de cristal terádrico para Willow en Desolace.",
    [7029] = "Llena el vial cerúleo cubierto en el estanque naranja de Maraudon. Aplica el vial cerúleo lleno a la hiedravil para que emerja el sucesor tóxico. Cura 8 plantas eliminando su sucesor tóxico e informa a Vark Marca de Guerra en la Aldea Cazasombras.",
    [7041] = "Llena el vial cerúleo cubierto en el estanque naranja de Maraudon. Aplica el vial cerúleo lleno a la hiedravil para que emerja el sucesor tóxico. Cura 8 plantas eliminando su sucesor tóxico e informa a Talendria en Punta de Nijel.",
    [7044] = "Recupera las 2 partes del cetro de Celebras: la vara y el diamante de Celebras. Encuentra el modo de hablar con Celebras.",
    [7046] = "Ayuda a Celebras el Redimido mientras reconstruye el cetro de Celebras. Habla con él después del ritual.",
    [7064] = "Mata a la princesa Theradras y ve a ver a Selendra cerca de la Aldea Cazasombras, en Desolace.",
    [7065] = "Mata a la princesa Theradras y ve a ver al vigilante Marandis a Punta de Nijel, en Desolace.",
    [7066] = "Busca a Remulos en Claro de la Luna y dale la semilla de vida.",
    [7067] = "Lee las instrucciones del Paria. Busca el Amuleto de Unidad en Maraudon y llévaselo al sur de Desolace.",
    [7068] = "Recoge 10 fragmentos oscuros en Maraudon y llévaselos a Uthel'nay a Orgrimmar.",
    [7070] = "Recoge 10 fragmentos oscuros en Maraudon y llévaselos al archimago Tervosh a Theramore, en la costa de Marjal Revolcafango.",
    [7081] = "Asalta un cementerio y vuelve con el sargento Durgen Pico Tormenta en las Montañas de Alterac.",
    [7082] = "Asalta un cementerio y vuelve con el cabo Teeka Gruñido Sangriento en las Montañas de Alterac.",
    [7101] = "Captura una torre enemiga y vuelve con el cabo Teeka Gruñido Sangriento en las Montañas de Alterac.",
    [7102] = "Destruye el estandarte de una torre enemiga o de un búnker y vuelve junto al sargento Durgen Pico Tormenta en las Montañas de Alterac.",
    [7121] = "Habla con el intendente Pico Tormenta.",
    [7122] = "Captura una mina que no esté bajo control de los Pico Tormenta y vuelve junto al sargento Durgen Pico Tormenta en las Montañas de Alterac.",
    [7123] = "Habla con el intendente de Lobo Gélido.",
    [7124] = "Captura una mina y vuelve con el cabo Teeka Gruñido Sangriento en las Montañas de Alterac.",
    [7141] = "Adéntrate en el Valle de Alterac, derrota al general Drek'thar de la Horda y vuelve junto a la prospectora Tallapiedra en las Montañas de Alterac.",
    [7142] = "Adéntrate en el Valle de Alterac y derrota al general enano Vanndar Pico Tormenta. Vuelve entonces junto a Voggah Agarre Letal en las Montañas de Alterac.",
    [7161] = "Viaja hasta la Caverna Zarpa Salvaje ubicada al sureste del campamento base en el Valle de Alterac y encuentra el estandarte Lobo Gélido. Devuélvele el estandarte al maestro de guerra Laggrond.",
    [7162] = "Viaja hasta la cueva Ala Gélida ubicada al suroeste de Dun Baldar en el Valle de Alterac y recupera el estandarte Pico Tormenta. Devuélveselo al teniente Haggerdin en las Montañas de Alterac.",
    [7181] = "Según cuenta la leyenda, el jefe de los poderosos trols Hacha Invernal parece dispuesto a sembrar el caos entre los habitantes del Valle de Alterac. Si Korrak se digna aparecer, destrúyelo y vuelve con el maestro de guerra Laggrond.",
    [7201] = "Viaja a las Profundidades de Roca Negra y recupera 10 esencias de los elementos. Tu primer impulso es buscar los gólems y a los creadores de gólems. Recuerdas que Vivian Lagrave también murmuró entre dientes algo sobre los elementales.",
    [7202] = "Según cuenta la leyenda, el jefe de los poderosos trols Hacha Invernal parece dispuesto a sembrar el caos entre los habitantes del Valle de Alterac. Si Korrak se digna aparecer, destrúyelo y vuelve con el teniente Haggerdin en las Montañas de Alterac.",
    [7223] = "Llévale 20 restos de armadura a Murgot Forjahonda en Dun Baldar.",
    [7224] = "Llévale 20 restos de armadura al herrero Regzar en Aldea Lobo Gélido.",
    [7241] = "Dirígete al Valle de Alterac en las Montañas de Alterac. Encuentra al maestro de guerra Laggrond y habla con él para empezar tu carrera como soldado Lobo Gélido; lo encontrarás en la entrada del túnel. El Valle de Alterac se sitúa al norte de Molino Tarren en la falda de las Montañas de Alterac.",
    [7261] = "Dirígete al Valle de Alterac en las Laderas de Trabalomas. Delante de la entrada del túnel, encuentra al teniente Haggerdin y habla con él. ¡Por la gloria de Barbabronce!",
    [7281] = "Viaja hasta el territorio de los Pico Tormenta y mata al comandante Karl Filis. Vuelve con el comandante Luis Philips cuando hayas completado la tarea.",
    [7282] = "Viaja hasta el territorio de los Lobo Gélido y mata al comandante Luis Philips Vuelve con el comandante Karl Filis cuando hayas completado la tarea.",
    [7301] = "Viaja hasta el territorio de los Lobo Gélido y busca al Comandante del aire Slidore, al comandante del aire Vipore y al comandante del aire Ichman. Vuelve con el comandante Duffy cuando hayas completado la misión.",
    [7302] = "Averigua qué fue del comandante del aire Guse, el Comandante del aire Jeztor y el comandante del aire Mulverick. Vuelve con el comandante Mulfort cuando hayas completado la misión.",
    [7321] = "Llévale 10 piezas de carne de tortuga y algunas especias calmantes al Christoph Jeffcoat en Molino Tarren.",
    [7361] = "Se te asignado la tarea de matar a los jugadores elfos de la noche en el Valle de Alterac. Mata a un elfo de la noche y llévale su cabeza decapitada a Najak Malditor en el Bastión Lobo Gélido.",
    [7362] = "Se te asignado la tarea de matar a los jugadores gnomos en el Valle de Alterac. Mata a un gnomo y llévale un mechón de la víctima a Ravak Tótem Siniestro en el Bastión Lobo Gélido.",
    [7363] = "Se te asignado la tarea de matar a los jugadores humanos en el Valle de Alterac. Mata a un humano y vuelve con el comandante Luis Philips (que deambula entre el frente y el Bastión Lobo Gélido) con un hueso de tu víctima. ¡Al fin se avecina una cura para la condición humana!",
    [7366] = "Se te asignado la tarea de matar a los jugadores renegados en el Valle de Alterac. Mata a un renegado y vuelve con el comandante Karl Filis (que deambula entre la Serrería y la Mina) con el corazón de tu víctima.",
    [7381] = "Si Korrak el Sanguinario vuelve por la Tierra de Disputa, encuéntralo y acaba con él. Llévale la calavera de Korrak al maestro de guerra Laggrond en las Laderas de Trabalomas.",
    [7382] = "Si Korrak el Sanguinario vuelve por la Tierra de Disputa, encuéntralo y acaba con él. Llévale la calavera de Korrak al teniente Haggerdin en las Laderas de Trabalomas.",
    [7383] = "Llena la ampolla de amatista y devuélvesela a Corithras Furia Lunar en Dolanaar.",
    [7441] = "Viaja a La Masacre y encuentra al diablillo Pusillín. Convence a Pusillín de que te dé el libro de Conjuros de Azj'Tordin, por cualquier medio. Si consigues hacerte con el libro de Conjuros, vuelve al Pabellón de Lariss de Feralas y busca a Azj'Tordin.",
    [7461] = "Debes destruir a los guardianes que rodean las 5 torres que controlan la Prisión de Immol'thar. Una vez desactivadas las torres, el campo de fuerza que rodea a Immol'thar se disipará. Entra en la Prisión de Immol'thar y erradica al demonio que hace guardia en su interior. Por último, haz frente al príncipe Tortheldrin en El Athenaeum. Si consigues completar esta misión, ve al patio a buscar a la ancestro Shen'dralar.",
    [7463] = "Viaja al Barrio Alabeo de La Masacre y mata al elemental de agua, Hidromilecio. Lleva la esencia de Hidromilecio al Tradicionalista Lydros que está en El Athenaeum.",
    [7481] = "Busca a Telmius Buscasueños en La Masacre. Vuelve al Campamento Mojache e informa al Sabio Korolusk de cualquier cosa que encuentres.",
    [7482] = "Busca a Telmius Buscasueños en La Masacre. Vuelve al Bastión Plumaluna a informar a la erudita Runaespina de lo que hayas encontrado.",
    [7483] = "Lleva 1 tratado sobre rapidez, 1 diamante negro prístino, 2 fragmentos luminosos grandes y 2 sangres de héroes al Tradicionalista Lydros a La Masacre para conseguir un arcanum de rapidez.",
    [7484] = "Lleva 1 tratado sobre enfoque, 1 diamante negro prístino, 4 fragmentos luminosos grandes y 2 pieles de Sombra al Tradicionalista Lydros a La Masacre para conseguir un arcanum de enfoque.",
    [7485] = "Lleva 1 tratado sobre protección, 1 diamante negro prístino, 2 fragmentos luminosos grandes y 1 costura desgarrada de abominación al Tradicionalista Lydros a La Masacre para conseguir un arcanum de protección.",
    [7486] = "Recoge tu recompensa en el arca de Hydraxis.",
    [7488] = "Lleva la Membrana de Lethtendris a Latronicus Lanzaluna al Bastión Plumaluna de Feralas.",
    [7489] = "Lleva la Membrana de Lethtendris a Talo Pezuñahendida al Campamento Mojache de Feralas.",
    [7490] = "Llévale la cabeza de Onyxia a Thrall en Orgrimmar.",
    [7491] = "Busca al señor supremo Runthak en el Valle de la Fuerza.",
    [7492] = "Ve al Campamento Mojache de Feralas y habla con Talo Pezuñahendida.",
    [7494] = "Habla con Latronicus Lanzaluna. Lo encontrarás en el Bastión Plumaluna de Feralas.",
    [7495] = "Llévale la cabeza de Onyxia al alto señor Bolvar Fordragón en Ventormenta.",
    [7496] = "Busca al mayor Mattingly en el Valle de los Héroes.",
    [7498] = "Devuelve el libro a sus legítimos dueños.",
    [7499] = "Devuelve el libro a sus legítimos dueños.",
    [7500] = "Devuelve el libro a sus legítimos dueños.",
    [7501] = "Devuelve el libro a sus legítimos dueños.",
    [7502] = "Devuelve el libro a sus legítimos dueños.",
    [7503] = "Devuelve el libro a sus legítimos dueños.",
    [7504] = "Devuelve el libro a sus legítimos dueños.",
    [7505] = "Devuelve el libro a sus legítimos dueños.",
    [7506] = "Devuelve el libro a sus legítimos dueños.",
    [7507] = "Devuelve el compendio de matar dragones de Nostro a El Athenaeum.",
    [7508] = "Entrega la hoja élfica roma Tradicionalista Lydros.",
    [7509] = "Debes conseguir que Onyxia escupa fuego sobre la hoja antigua sin templar. Una vez hecho, recógela, su hoja estará candente. Pero ten cuidado: una hoja candente no permanecerá así para siempre, no tienes tiempo que perder. Antes de volver a mí, tienes que terminar lo empezado, debes matar a la bestia e introducir la hoja candente en su cadáver. Hazlo y Quel'Serrar será tuya.",
    [7562] = "Habla con Mor'zul Sangredoble en el Altar de la Tempestad en Las Estepas Ardientes.",
    [7563] = "Llévale 30 botellas de sangre de bestia embravecida a Mor'zul Sangredoble en Las Estepas Ardientes.",
    [7564] = "Llévale el estuche de sangre a Gorzeeki Ojovago al Altar de la Tempestad, en Las Estepas Ardientes.",
    [7581] = "Viaja a La Masacre en Feralas y consigue 15 muestras de sangre de sátiro del sátiro Mala Hierba que habita en el Barrio Alabeo. Cuando hayas acabado, ve a ver a Daio a la Escara Impía.",
    [7582] = "Viaja a la Garganta Negro Rumor en Cuna del Invierno y recoge 5 Lágrimas de los Hederine de los demonios Hederine que ocupan la garganta. Cuando hayas cumplido tu tarea, ve a ver a Daio a la Escara Impía.",
    [7583] = "Aventúrate en la Escara Impía y localiza a un comandante Guardia apocalíptico. Utiliza la prisión de cristal resplandeciente para atrapar al comandante Guardia apocalíptico. Prepárate para una sucesión de ataques pues el demonio intentará escapar. Si tienes éxito, llévale el Guardia apocalíptico encarcelado a Daio, en la Escara Impía.",
    [7601] = "Habla con Diblis en Frondavil.",
    [7602] = "Diblis de Frondavil te ha pedido que le lleves 3 esencias viles impecables que provengan de 3 lugares distintos. Los sátiros Legashi de Azshara tienen la esencia vil impecable de su región. Los Legionarios Jaedenar de Jaedenar tienen la esencia vil impecable de su región. Los guardias viles de Las Tierras Devastadas tienen la esencia vil impecable de su región. Reúne las esencias viles impecables y vuelve con Diblis a Frondavil.",
    [7603] = "Busca los restos de Kroshius en la Cañada Gran Cicatriz de Frondavil. Cuando localices sus restos, utiliza el fuego vil cerca de ellos y espera el regreso de Kroshius. Cuando el infernal se haya despertado, acaba con él y extrae de su cuerpo el núcleo infernal de Kroshius. Lleva el núcleo infernal de Kroshius a Niby el Todopoderoso a Frondavil.",
    [7604] = "Entrégale el contrato de La Hermandad del Torio a Lokhtos Tratoscuro si quieres recibir los planes de Sulfuron.",
    [7622] = "Salva a 50 campesinos antes de que 15 sean asesinados. Habla con Eris Feleste si tienes éxito. Puedes ver el Poste de la muerte para ver cuántos campesinos han sido asesinados.",
    [7623] = "Cómprale pociones enigmáticas a Gorzeeki Ojovago en el Altar de la Tempestad en Las Estepas Ardientes. Usa las pociones para viajar por Jaedenar en Frondavil y habla con Lord Pesadilla en el interior de la Guarida Sombría.",
    [7624] = "Enfréntate a Ulathek y llévale el corazón del traidor a Lord Pesadilla en Jaedenar.",
    [7625] = "Cómprale polvo estelar xorothiano a Ur'dan en el interior de la Guarida Sombría en Jaedenar, en Frondavil. Llévaselo a Gorzeeki Ojovago en Las Estepas Ardientes.",
    [7626] = "Llévale 2 elixires de poder de las sombras a Gorzeeki Ojovago en Las Estepas Ardientes.",
    [7627] = "Llévale 6 fragmentos luminosos grandes y 25 minerales de hierro negro a Gorzeeki Ojosalvajes en Las Estepas Ardientes.",
    [7628] = "Lleva 3 dragontinas negras a Gorzeeki Ojovago a Las Estepas Ardientes.",
    [7629] = "Llévale el diablillo en un tarro al laboratorio de alquimia de Scholomance. Después de crear el papiro llévale el tarro a Gorzeeki Ojovago.",
    [7630] = "Lleva una barra de arcanita a Gorzeeki Ojosalvajes a Las Estepas Ardientes.",
    [7631] = "Lee las instrucciones de Mor'zul. Invoca a un corcel nefasto xorothiano, derrótalo y después vincula su espíritu al tuyo.",
    [7632] = "Encuentra al dueño de la hoja petrificada vieja. Buena suerte, <nombre>; este es un mundo enorme...",
    [7634] = "Hastat el anciano te ha pedido que le lleves 1 tendón de dragón Azul maduro. Si lo encuentras, llévaselo a Hastat a Frondavil.",
    [7635] = "Estoma el Anciano te ha pedido que le lleves 1 tendón de dragón Negro maduro. Si lo encontraras, llévaselo a Estoma a Frondavil.",
    [7636] = "Debes encontrar y destruir a estos 4 corruptores demoníacos: Simone la Seductora. Klinfran el Enloquecido. Solenor el Destripador. Artorius el Fatídico. Destruye a estas criaturas, vuelve a Frondavil y entrega sus cabezas a Vartrus el Ancestro. Busca pistas de su paradero en la corteza petrificada. DEBES completar esta misión tú <solo/sola>.",
    [7637] = "Viaja a Forjaz y consigue el incensario de exorcismos del sumo sacerdote Rohan. Tendrás que hacer una donación de 150 monedas de oro para conseguirlo.",
    [7638] = "Habla con Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta.",
    [7639] = "Devuelve el incensario de exorcismos a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta.",
    [7640] = "Utiliza el incensario de exorcismos para expulsar los espíritus que atormentan el Valle del Terror. Cuando hayas matado 25 espíritus del Valle del Terror, vuelve a ver a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta.",
    [7641] = "Habla con Grimand Elmore en el Distrito de los Enanos, en Ventormenta.",
    [7642] = "Lleva 40 paños rúnicos, 6 barras de arcanita, 10 lágrimas de Arthas, 5 viales de agua sagrada de Stratholme y 150 monedas de oro a Grimand Elmore en el Distrito de los Enanos de Ventormenta.",
    [7643] = "Consigue comida para caballos para alimentar a un espíritu equino. Por lo visto, Merideth Carlson, en Costasur, tiene esa comida. Ve a la mazmorra de La Masacre, en Feralas y mata a Tendris Alabeo. Al hacerlo, liberarás al antiguo espíritu equino. Dale la comida para caballos y lo aplacarás. Por último, dale la gualdrapa de arcanita para que la bendiga.",
    [7644] = "Devuelve la gualdrapa de arcanita bendita a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta.",
    [7645] = "Consigue 20 galletas enriquecidas con maná, ingrediente principal del alimento especial para caballos, y llévaselas a Merideth Carlson a las Laderas de Trabalomas, en Costasur. Solo El Alba Argenta fabrica esas galletas. También tienes que darle 50 piezas de oro para aplacar su orgullo herido.",
    [7646] = "Lleva un diamante de Azeroth y un diamante negro prístino a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta.",
    [7647] = "Utiliza el cristal de adivinación en el centro del sótano de El Gran Osario en Scholomance. Al hacerlo, aparecerán los espíritus que tienes que juzgar. Si derrotas a esos espíritus, aparecerá el Caballero de la Muerte Atracoscuro. Acaba con él y reclama el alma perdida del destrero caído. Entrega el alma redimida del destrero y la gualdrapa encantada bendecida al destrero caído de Atracoscuro.",
    [7648] = "Lleva la gualdrapa de arcanita a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta para que la inspeccione.",
    [7649] = "Devuelve el libro a sus legítimos dueños.",
    [7650] = "Devuelve el libro a sus legítimos dueños.",
    [7651] = "Devuelve el libro a sus legítimos dueños.",
    [7667] = "Si te interesa ayudar a Sagorne Montacresta, llévale 1 diamante de Azeroth y 1 diamante negro prístino al Valle de la Sabiduría, en Orgrimmar.",
    [7670] = "Habla con Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta.",
    [7701] = "El traidor Hierro Negro llamado sobrestante Maltorius está en La Fosa de la Escoria de La Caldera, en La Garganta de Fuego. Mátalo y lleva su cabeza al capitán de vigía Lolo Zancalarga a La Garganta de Fuego para recibir tu recompensa.",
    [7703] = "Encuentra el guante del Poderío de Gordok y llévaselo al capitán Kromcrush a La Masacre. Según Kromcrush, una \"historia muy, muy vieja\" dice que Tortheldrin, un elfo \"asqueroso\" que se llamaba a sí mismo príncipe, robó el guantelete a uno de los reyes de Gordok.",
    [7721] = "Reúne 10 núcleos de elemental de agua de los elementales marinos y de los rocíos marinos que hay en La Costa Olvidada de Feralas, y llévaselos a Zorbin Hipnoviento, que está cerca del embarcadero.",
    [7722] = "Busca los diseños secretos: flujo ígneo robados por el sobrestante Maltorius en La Fosa de la Escoria de La Caldera. Llévaselos al herrero maestro Burninate a La Garganta de Fuego.|n",
    [7723] = "Hansel Manospesadas quiere que mates 20 gólems de guerra pesados. Suelen estar cerca de La Caldera en La Garganta de Fuego. Después ve a ver a Hansel a La Garganta de Fuego.",
    [7724] = "Hansel Manospesadas quiere que mates 20 arañas de lava superiores en La Garganta de Fuego. Las encontrarás en las mesetas y los estanques de lava de La Garganta de Fuego. Cuando hayas matado suficientes arañas de lava superiores ve a ver a Hansel Manospesadas a La Garganta de Fuego.",
    [7725] = "Utiliza el Ultra-reductor de Zorbin para encoger a cualquier gigante que encuentres en Feralas a un tamaño más manejable. Lleva 10 residuos de miniaturización encontrados en las versiones encogidas de los gigantes a Zorbin Hipnoviento, al embarcadero de La Costa Olvidada de Feralas.",
    [7726] = "Reúne 6 núcleos de elemental de agua de los elementales marinos y los rocíos marinos que hay en La Costa Olvidada de Feralas, y llévaselos a Zorbin Hipnoviento, que está cerca del embarcadero.",
    [7727] = "Hansel Manospesadas quiere que mates 20 incendosaurios. Suelen estar en los estanques de lava de La Fosa de la Escoria. La Fosa de la Escoria está en La Caldera de La Garganta de Fuego. Cuando hayas matado suficientes incendosaurios ve a ver a Hansel Manospesadas a La Garganta de Fuego.",
    [7728] = "Encuentra la tobera y el catalejo y llévaselos al capataz Scrange a La Garganta de Fuego. Lo único que sabes es que fueron robados por enanos Hierro Negro. La tobera es una herramienta de herrero y el catalejo es un instrumento muy valioso para los oteadores.",
    [7729] = "Mata a 15 Capataces y 15 esclavistas Hierro Negro y ve a ver al capataz Scrange a La Garganta de Fuego.",
    [7730] = "Lleva 20 caparazones Zukk'ash a Hadoken Zanco Veloz al Campamento Mojache en Feralas.",
    [7731] = "Derrota al latigador con aguijón en Las Galerías Retorcidas y lleva sus glándulas a Hadoken Zanco Veloz al Campamento Mojache en Feralas.",
    [7732] = "Entrega a Zilzibin Tambor Sabio el informe del campamento Mojache Zukk'ash. Reside en La Calle Mayor de Orgrimmar.",
    [7733] = "Lleva 10 pellejos de yeti Cicatriz de Rabia a Pratt McGrubben al Bastión Plumaluna en Feralas.",
    [7734] = "Lleva 10 pellejos de yeti Cicatriz de Rabia a Jangdor Zanco Veloz al Campamento Mojache de Feralas.",
    [7735] = "Lleva el pellejo de yeti prístino a Pratt McGrubben al Bastión Plumaluna de Feralas.",
    [7738] = "Lleva los pellejos de yeti perfecto a Jangdor Zanco Veloz al Campamento Mojache de Feralas.",
    [7761] = "¡Será estúpido ese orco! Al parecer, tienes que encontrar la enseña y ganar la marca de Drakkisath para poder acceder al orbe de orden. Según la carta, el general Drakkisath guarda la enseña. Quizás deberías investigarlo.",
    [7781] = "Llévale la cabeza de Nefarian al alto señor Bolvar Fordragón en Ventormenta.",
    [7782] = "Vete al Valle de los Héroes, en la Ciudad de Ventormenta, y habla con el mariscal de campo Petraponte.",
    [7783] = "Llévale la cabeza de Nefarian a Thrall en Orgrimmar.",
    [7784] = "Habla con el alto señor supremo Colmillosauro en Orgrimmar. Te espera en el Valle de la Fuerza.",
    [7785] = "Examina la vasija de renacer y devuélvesela al alto señor Demitrian.",
    [7786] = "Para liberar a Thunderaan el Hijo del Viento de su cárcel, debes entregarle al alto señor Demitrian en Silithus la mitad izquierda y la derecha de las ataduras del Hijo del Viento, 10 barras de elementium y la esencia del Señor del Fuego.",
    [7787] = "Lleva la hoja besada por el viento durmiente al alto señor Demitrian.",
    [7810] = "Habla con Corto John Mitril en la Arena de la Vega de Tuercespina.",
    [7815] = "Katoom el Pescador, del Poblado Sañadiente en las Tierras del Interior, quiere que mates 15 tortugas quijaforte marinas. Ve a verlo cuando hayas terminado.",
    [7816] = "Katoom el Pescador, del Poblado Sañadiente en las Tierras del Interior, quiere que mates a Gammerita y que le saques el cebo del estómago. Dijo que Gammerita está en la costa con las otras tortugas.",
    [7828] = "El montero Markhor, del Poblado Sañadiente en las Tierras del Interior, quiere que mates 15 acechadores melenargenta y 15 aulladores melenargenta. Vuelve a verlo cuando hayas terminado. Markhor dijo que los lobos se ocultan entre la maleza en las Tierras del Interior.",
    [7829] = "El montero Markhor, del Poblado Sañadiente en las Tierras del Interior, quiere que mates 20 lechubestias salvajes. Vuelve a verlo cuando hayas terminado. Markhor dijo que las lechubestias salvajes se ocultan entre la maleza en las Tierras del Interior.",
    [7830] = "El montero Markhor, del Poblado Sañadiente en las Tierras del Interior, quiere que mates a un Señor del Cielo y le lleves la péndola. Dijo que son una raza poco común que se extiende por toda la región.",
    [7839] = "El herrero Esco de Poblado Sañadiente, en las Tierras del Interior, quiere que encuentres y le lleves sus herramientas perdidas. Dijo que las herramientas pueden estar en uno de los templos Vilrama en la zona noreste de las Tierras del Interior. Mira también en Roca Oculta.",
    [7840] = "Lard, del Poblado Sañadiente en las Tierras del Interior, quiere que vayas a buscar su almuerzo. Llévaselo cuando lo encuentres. Dijo que se lo dejó en la isla del norte. Ten cuidado con los trols Vilrama.",
    [7841] = "Otho Moji'ko del Poblado Sañadiente, en las Tierras del Interior, quiere que mates a 15 miembros de la avanzada Vallealto, 15 exploradores Vallealto, 15 tiradores Vallealto y 15 forestales Vallealto. Vuelve a verlo cuando hayas terminado. Los elfos nobles Vallealto están en la Avanzada Quel'Danil, al noroeste de las Tierras del Interior.",
    [7842] = "Otho Moji'ko del Poblado Sañadiente, en las Tierras del Interior, quiere que le lleves 10 plumas elegantes largas de los grifos de las Tierras del Interior. Vuelve a verlo cuando hayas terminado. Encontrarás grifos por todas las Tierras del Interior.",
    [7843] = "Otho Moji'ko del Poblado Sañadiente, en las Tierras del Interior, quiere que vayas a Pico Nidal, al oeste de la región, y coloques el mensaje final junto al pozo del centro del pueblo. Vuelve a verlo cuando hayas terminado. Ten cuidado con los belicosos enanos Martillo Salvaje y los miembros indisciplinados de la Alianza.",
    [7844] = "La mística Yayo'jin del Poblado Sañadiente, en las Tierras del Interior, quiere que mates a 30 arrancacabelleras Vilrama y a 2 veritas Vilrama. Vuelve a verla cuando hayas terminado. Yayo'jin dijo que estos trols suelen estar cerca de los templos de Shaol'watha y Agol'watha, en las zonas norte y noreste de las Tierras del Interior.",
    [7845] = "Primigenia Colmillopartido del Poblado Sañadiente, en las Tierras del Interior, quiere que rescates a su compañero, el anciano Colmillopartido, que está en Jintha'alor. Te han dicho que lo tienen prisionero en la cima de Jintha'alor, la capital vilrama al sur de las Tierras del Interior.",
    [7846] = "El anciano Colmillopartido de Jintha'alor quiere que mates a Hitah'ya la Guardiana para quitarle la llave de sus grilletes. Vuelve a verlo cuando hayas conseguido la llave.",
    [7847] = "El anciano Colmillopartido de Jintha'alor quiere que informes de su rescate a Primigenia Colmillopartido en el Poblado Sañadiente.",
    [7848] = "Acércate al portal de entrada del Núcleo de Magma en las Profundidades de Roca Negra y recoge un trozo del Núcleo. Llévaselo a Lothos Levantagrietas a la Montaña Roca Negra.",
    [7849] = "El montero Markhor de Poblado Sañadiente, en las Tierras del Interior, quiere que le lleves los restos de su hermano gemelo. Llévale la calavera y los huesos de Malkhor. Dijo que los Vilrama habían arrojado los restos de su hermano a los mocos y los lobos. También dijo que hay una fosa llena de mocos en Jintha'alor, además de una guarida de lobos, ambas cerca de la parte alta del templo.",
    [7850] = "Primigenia Colmillopartido del Poblado Sañadiente, en las Tierras del Interior, quiere que recojas 10 vasijas de sangre corrupta en Jintha'alor. Vuelve a verla cuando hayas terminado la tarea.",
    [7861] = "Te han ordenado que mates a la sacerdotisa vil Hexx y a 20 guardias Aman'zasi Vilrama. Ve a ver a Primigenia Colmillopartido al Poblado Sañadiente en las Tierras del Interior cuando hayas terminado. Encontrarás a la sacerdotisa vil Hexx y a los guardias en la cima de Jintha'alor, en las Tierras del Interior.",
    [7862] = "Se te ha asignado la tarea de aniquilar a 20 rabiosos Vilrama, 20 cazadores de las Sombras Vilrama, 20 bebesangres Vilrama y 20 comealmas Vilrama. Cuando hayas terminado, ve a ver a Primigenia Colmillopartido al Poblado Sañadiente, en las Tierras del Interior.",
    [7877] = "Vuelve a El Athenaeum y encuentra el tesoro de los Shen'dralar. ¡Reclama tu recompensa!",
    [7907] = "Lleva la baraja de Bestias a la Feria de la Luna Negra cuando pase por la ciudad.",
    [7927] = "Lleva la baraja de Portales a la Feria de la Luna Negra cuando pase por la ciudad.",
    [7928] = "Lleva la baraja de Señores de la Guerra a la Feria de la Luna Negra cuando pase por la ciudad.",
    [7929] = "Lleva la baraja de Elementales a la Feria de la Luna Negra cuando pase por la ciudad.",
    [8053] = "Lleva a Jin'rokh el Rompedor unas ataduras Hakkari primigenias. También debes tener una reputación mínima de <amistoso/amistosa> con la tribu Zandalar. Jin'rokh el Rompedor está en Isla Yojamba, en la Vega de Tuercespina.",
    [8054] = "Lleva los siguientes Dechados de Poder de Zul'Gurub a Jin'rokh el Rompedor: un chal Hakkari primigenio. También debes tener una reputación mínima de honorable con la tribu Zandalar. Jin'rokh el Rompedor está en Isla Yojamba, en la Vega de Tuercespina.",
    [8055] = "Lleva los siguientes Dechados de Poder de Zul'Gurub a Jin'rokh el Rompedor: un tabardo Hakkari primigenio. También debes tener una reputación mínima de <venerado/venerada> con la tribu Zandalar. Jin'rokh el Rompedor está en Isla Yojamba, en la Vega de Tuercespina.",
    [8056] = "Lleva a Maywiki de Zuldazar un cabestrillo Hakkari primigenio. También debes tener una reputación mínima de <amistoso/amistosa> con la tribu Zandalar. Maywiki de Zuldazar está en Isla Yojamba, en la Vega de Tuercespina.",
    [8057] = "Lleva a Maywiki de Zuldazar un puntal Hakkari primigenio. También debes tener una reputación mínima de <amistoso/amistosa> con la tribu Zandalar. Maywiki de Zuldazar está en Isla Yojamba, en la Vega de Tuercespina.",
    [8058] = "Lleva a Jin'rokh el Rompedor un cabestrillo Hakkari primigenio. También debes tener una reputación mínima de <amistoso/amistosa> con la tribu Zandalar. Jin'rokh el Rompedor está en Isla Yojamba, en la Vega de Tuercespina.",
    [8059] = "Lleva a Al'tabim el que todo lo ve un puntal Hakkari primigenio. También debes tener una reputación mínima de <amistoso/amistosa> con la tribu Zandalar. Al'tabim el que todo lo ve está en Isla Yojamba, en la Vega de Tuercespina.",
    [8060] = "Lleva a Al'tabim el que todo lo ve unas ataduras Hakkari primigenias. También debes tener una reputación mínima de <amistoso/amistosa> con la tribu Zandalar. Al'tabim el que todo lo ve está en Isla Yojamba, en la Vega de Tuercespina.",
    [8061] = "Lleva a Al'tabim el que todo lo ve un puntal Hakkari primigenio. También debes tener una reputación mínima de <amistoso/amistosa> con la tribu Zandalar. Al'tabim el que todo lo ve está en Isla Yojamba, en la Vega de Tuercespina.",
    [8062] = "Lleva los siguientes Dechados de Poder de Zul'Gurub a Falthir el Ciego: unas ataduras Hakkari primigenias. También debes tener una reputación mínima de <amistoso/amistosa> con la tribu Zandalar. Falthir el Ciego está en Isla Yojamba, en la Vega de Tuercespina.",
    [8063] = "Lleva los siguientes Dechados de Poder de Zul'Gurub a Falthir el Ciego: un cabestrillo Hakkari primigenio. También debes tener una reputación mínima de <amistoso/amistosa> con la tribu Zandalar. Falthir el Ciego está en Isla Yojamba, en la Vega de Tuercespina.",
    [8064] = "Lleva a Maywiki de Zuldazar un fajín hakkari primigenio. Maywiki de Zuldazar está en Isla Yojamba, en Vega de Tuercespina. También debes tener una reputación de honorable con Zandalar.",
    [8065] = "Lleva a Maywiki de Zuldazar un tabardo Hakkari primigenio. Maywiki de Zuldazar está en Isla Yojamba, en Vega de Tuercespina. También debes tener una reputación de <venerado/venerada> con Zandalar.",
    [8066] = "Lleva los siguientes Dechados de Poder de Zul'Gurub a Falthir el Ciego: un chal Hakkari primigenio. También debes tener una reputación mínima de honorable con la tribu Zandalar. Falthir el Ciego está en Isla Yojamba, en la Vega de Tuercespina.",
    [8067] = "Lleva los siguientes Dechados de Poder de Zul'Gurub a Falthir el Ciego: una égida Hakkari primigenia. También debes tener una reputación mínima de <venerado/venerada> con la tribu Zandalar. Falthir el Ciego está en Isla Yojamba, en la Vega de Tuercespina.",
    [8068] = "Lleva a Al'tabim el que todo lo ve un chal Hakkari primigenio. También debes tener una reputación mínima de honorable con la tribu Zandalar. Al'tabim el que todo lo ve está en Isla Yojamba, en la Vega de Tuercespina.",
    [8069] = "Lleva a Al'tabim el que todo lo ve una casaca hakkari primigenia. También debes tener una reputación mínima de <venerado/venerada> con la tribu Zandalar. Al'tabim el que todo lo ve está en Isla Yojamba, en la Vega de Tuercespina.",
    [8070] = "Lleva a Al'tabim el que todo lo ve un fajín hakkari primigenio. También debes tener una reputación mínima de honorable con la tribu Zandalar. Al'tabim el que todo lo ve está en Isla Yojamba, en la Vega de Tuercespina.",
    [8071] = "Lleva a Al'tabim el que todo lo ve una égida Hakkari primigenia. También debes tener una reputación mínima de <venerado/venerada> con la tribu Zandalar. Al'tabim el que todo lo ve está en Isla Yojamba, en la Vega de Tuercespina.",
    [8072] = "Lleva los siguientes Dechados de Poder de Zul'Gurub a Falthir el Ciego: una faja Hakkari primigenia. También debes tener una reputación mínima de honorable con la tribu Zandalar. Falthir el Ciego está en Isla Yojamba, en la Vega de Tuercespina.",
