    [8446] = "Encuentra a alguien que pueda descifrar el significado del objeto envuelto en pesadillas. Quizás un druida de gran poder pueda ayudarte.",
    [8447] = "Espera a que el Guardián Remulos del Claro de la Luna purifique el objeto envuelto en pesadillas.",
    [8460] = "Grazle quiere que demuestres tu valía matando a 6 guerreros Muertobosque, 6 abrecaminos Muertobosque y 6 jardineros Muertobosque. Cuando lo hayas hecho, vuelve con él al sur de Frondavil, cerca del Santuario Esmeralda.",
    [8461] = "Nafien quiere que mates a 6 vigías del cubil Muertobosque, 6 vengadores Muertobosque y 6 chamanes Muertobosque. Luego, vuelve a buscarlo al norte de Frondavil, cerca de la entrada del Bastión Fauces de Madera.",
    [8462] = "Viaja hacia el norte por el camino principal de Frondavil y habla con el fúrbolg Nafien. Está haciendo guardia en la entrada del Bastión Fauces de Madera.",
    [8464] = "Salfa quiere que mates 8 chamanes Nevada, 8 vigías del cubil Nevada y 8 ursas Nevada. Salfa está a las puertas del Bastión Fauces de Madera en Cuna del Invierno.",
    [8465] = "Viaja por el Bastión Fauces de Madera y sal a Cuna del Invierno. Habla con Salfa, que está haciendo guardia en la entrada del Bastión Fauces de Madera.",
    [8470] = "Lleva el tótem de ritual Muertobosque al interior del Bastión Fauces de Madera. A ver si alguno de los fúrbolgs que hay en él sabe dar uso al objeto. Los Fauces de Madera no hablarán contigo si no tienes un nivel de reputación neutral o superior con ellos.",
    [8471] = "Lleva el tótem de ritual Nevada al Bastión Fauces de Madera y averigua si alguno de los fúrbolgs sabe de su utilidad. Los Fauces de Madera no hablarán contigo si tu reputación con ellos no es como mínimo de neutral.",
    [8481] = "Clava la antorcha para invocar demonios en la entrada de la cueva del gran jefe Nevada en el Poblado Nevada de los fúrbolgs. Derrota al demonio y consigue la esencia de Xandivious para Gorn el Tuerto",
    [8484] = "Llévale la ofrenda de paz de los Fauces de Madera al rey Magni Barbabronce de Forjaz.",
    [8485] = "Llévale la ofrenda de paz de los Fauces de Madera a Thrall en Orgrimmar.",
    [8492] = "Llévale 20 lingotes de cobre al sargento Petrocejas en La Sala Militar de Forjaz.",
    [8493] = "Llévale 20 lingotes de cobre al sargento Petrocejas en la base aérea de Dun Morogh.",
    [8494] = "Llévale 20 barras de hierro al cabo Carnes en La Sala Militar de Forjaz.",
    [8495] = "Llévale 20 barras de hierro al cabo Carnes en la base aérea de Dun Morogh.",
    [8496] = "Lleva 30 vendas de paño rúnico gruesas, 30 vendas de seda gruesas y 30 vendas de tejido mágico gruesas a Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas X para poder completar la misión.",
    [8498] = "Consigue las órdenes de batalla Crepusculares y llévaselas al comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas tácticas X para poder completar la misión.",
    [8499] = "Llévale 20 barras de torio a Dama Trenzado en La Sala Militar de Forjaz.",
    [8500] = "Llévale 20 barras de torio a Dama Trenzado en la base aérea de Dun Morogh.",
    [8501] = "Mata 30 aguijoneros Colmen'Ashi y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate XII para poder completar la misión.",
    [8502] = "Mata 30 trabajadores Colmen'Ashi y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate III para poder completar la misión.",
    [8503] = "Llévale 20 algas estranguladoras al soldado Draxlegauge en La Sala Militar de Forjaz.",
