    [8534] = "Contacta con el explorador Cenarion Azenel en Colmen'Zora y entrega el informe de exploración de Colmen'Zora a Clamavientos Cuerno Digno en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VI para poder completar la misión.",
    [8535] = "Invoca y mata a un Templario vetusto y preséntate ante Bor Ferocrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas IV para poder completar la misión.",
    [8536] = "Invoca y mata a un Templario de tierra y preséntate ante Bor Ferocrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas III para poder completar la misión.",
    [8537] = "Invoca y mata a un templario Carmesí y preséntate ante Bor Ferocrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas II para poder completar la misión.",
    [8538] = "Invoca y mata al duque de las Brasas, al duque de las Profundidades, al duque de los Céfiros y al duque de las Esquirlas y preséntate ante el comandante Mar'alith en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas V para poder completar la misión.",
    [8539] = "Mata 30 hermanas de la colmena de Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate V para poder completar la misión.",
    [8540] = "Lleva 3 botas de mitril ornamentado a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas II para poder completar la misión.",
    [8541] = "Lleva 10 piedras de pulir densas, 10 piedras de pulir sólidas y 10 piedras de pulir pesadas a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas III para poder completar la misión.",
