    [97326] = "Llévale 8 rocas lisas a Thra detrás del Fuerte Grommash.",
    [97328] = "Recupera 8 cargamentos robados de las Ruinas de Zul'Kunda en Vega de Tuercespina y entrégale tu botín a alguien en Bahía del Botín.",
    [97329] = "Lleva la llave primitiva que obtuviste de los trols a Zimmix Chisporroteo en las Ruinas de Zul'Kunda en la Vega de Tuercespina.",
    [97331] = "Escolta a Zimmix Chisporroteo fuera de las Ruinas de Zul'Kunda y luego informa al jefe de embarcadero Lozgil en Bahía del Botín sobre el rescate exitoso.",
    [97332] = "Entrega el paquete reordenado dos veces al maestro de muelles Zumbidoz en Puerto Polvomecha en los Claros del Río.",
    [97378] = "Llévale el ala de Escamaespejo a Melor Pezuña Pétrea en Cima del Trueno.",
    [97386] = "El comandante Aggro'gosh del Campamento Grom'gol quiere que mates a los ogros en el Túmulo Ogro Mosh'Ogg.",
    [97405] = "Knaz Flamerrada quiere que mates 3 creaconjuros Mosh'Ogg, 3 belicistas Mosh'Ogg, 3 aplastadores Mosh'Ogg y 3 chamanes Mosh'Ogg en el Túmulo Ogro Mosh'Ogg.",
    [97420] = "Consigue 4 tambores de petróleo crudo de las operaciones de Los Ventura y Cía. en Lago Nazferiti, y vuelve con Knaz Flamerrada en Vega de Tuercespina.",
    [97453] = "Mata 6 malezas carnívoras al sur de Grom'gol y luego informa a la madre de Gemmil.",
    [97485] = "Cómprale un fardo de hierbas a Nida, la herborista; un fardo de ramitas de cedro a Nata, la proveedora de encantamiento; un hilo de tendón a Mahu, el proveedor de peletería; y sílex y yesca ceremoniales a Naal, el proveedor de cocina. Combina estos objetos y esparce el incienso por el Alto de los Cazadores.",
    [97530] = "El jefe de seguridad Pasaquillas de Puerto Bonvapor en Tanaris quiere que recuperes un brazalete particularmente brillante, que se ha perdido cerca de la base de los ogros Machacadunas.",
    [97534] = "Quinn quiere que recuperes 7 partes de restos de desertor y regreses con ella en Gadgetzan.",
    [97536] = "Jhordy Lapforge quiere verte luego de que hayas arrojado el cajón de los residuos radiactivos en el desierto de Tanaris a una distancia segura de Gadgetzan y de otros tipos de basura.",
    [97538] = "Tah Pezuña Invernal en Cima del Trueno quiere 30 vainas de hierba oscura del Lago Mirkfallon.",
    [97539] = "Llévale 12 pedazos de seda de araña quirúrgica al Doctor Gregory Victor en Sentencia, en las Tierras Altas de Arathi.",
    [97540] = "Ahora que Tooga se ha refrescado, muéstrale el camino de regreso hacia su esposa, Thorta.",
    [97558] = "Lleva 8 membranas de alas de murciumbrío, 6 pellejos de can oscuro y 3 pieles de múrloc Anca Vil a Shelene Rhobart.",
    [97583] = "Compra fango de baba nutritivo y vuelve con tu inquieta y amistosa babosa. Si parece cansada, baila con ella de nuevo para llamar su atención.",
    [97617] = "Recupera 8 artefactos no investigados, un casco de minería de la Liga de Expedicionarios y un azadón prístino y llévaselos a Dorgaron en el límite entre Loch Modan y las Tierras Inhóspitas.",
    [97663] = "Asesina a los ogros en Terraseca para recuperar los suministros robados de Mus'hale y úsalos para calcar las piedras grabadas en los alrededores. Al terminar, regresa con Mus'hale en Kargath.",
    [97884] = "Viaja a Claro Soleado en Claros del Río y recupera el tomo de Técnicas de herrería de la familia Tremayne.",
    [97891] = "Llévale la poción inestable al doctor Martin Felben en El Apothecarium antes de que se agote el tiempo.",
    [97894] = "Ve a ver a Gorbold Mano de Acero en Auberdine, en Costa Oscura. Borgus mencionó que puedes tomar un barco en el muelle más austral del Puerto de Ventormenta para llegar allí.",
